{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or Replace Table mapleMonk.Saadaa_DB_Facebook_customcampaigns_data as select * from (( select optimization_goal, account_currency, conversions, inline_link_clicks, reach, adset_name, objective, frequency, action_values, campaign_name, account_name, spend, date_stop, campaign_id, outbound_clicks, quality_ranking, ad_name, impressions, ad_id, date_start, account_id, conversion_values, inline_post_engagement, adset_id, clicks, created_at, actions, _airbyte_ab_id, _airbyte_emitted_at from mapleMonk.Saadaa_DB_Facebook_customcampaigns_data ) union all ( WITH parsed AS ( Select * from ( SELECT _airbyte_ab_id, _airbyte_emitted_at, PARSE_JSON(_airbyte_data, wide_number_mode => \'round\') AS d FROM maplemonk._airbyte_raw_custom_facebook_marketing_saadaa_fb_customcampaigns_data where date(_airbyte_emitted_at) >= DATE_ADD(DATE (coalesce((select max(date(_airbyte_emitted_at)) date from mapleMonk.Saadaa_DB_Facebook_customcampaigns_data),\'2020-01-01\')), INTERVAL -3 DAY) ) QUALIFY ROW_NUMBER() OVER(PARTITION BY LAX_STRING(d.ad_id),LAX_STRING(d.date_start) ORDER BY _airbyte_emitted_at DESC) = 1 ) SELECT LAX_STRING(d.optimization_goal) AS optimization_goal, LAX_STRING(d.account_currency) AS account_currency, ARRAY(SELECT TO_JSON_STRING(e) FROM UNNEST(JSON_QUERY_ARRAY(d, \'$.conversions\')) AS e) AS conversions, LAX_INT64(d.inline_link_clicks) AS inline_link_clicks, LAX_INT64(d.reach) AS reach, LAX_STRING(d.adset_name) AS adset_name, LAX_STRING(d.objective) AS objective, LAX_INT64(d.frequency) AS frequency, ARRAY(SELECT TO_JSON_STRING(e) FROM UNNEST(JSON_QUERY_ARRAY(d, \'$.action_values\')) AS e) AS action_values, LAX_STRING(d.campaign_name) AS campaign_name, LAX_STRING(d.account_name) AS account_name, LAX_FLOAT64(d.spend) AS spend, date(LAX_STRING(d.date_stop)) AS date_stop, LAX_FLOAT64(d.campaign_id) AS campaign_id, ARRAY(SELECT TO_JSON_STRING(e) FROM UNNEST(JSON_QUERY_ARRAY(d, \'$.outbound_clicks\')) AS e) AS outbound_clicks, LAX_STRING(d.quality_ranking) AS quality_ranking, LAX_STRING(d.ad_name) AS ad_name, LAX_INT64(d.impressions) AS impressions, LAX_STRING(d.ad_id) AS ad_id, date(LAX_STRING(d.date_start)) AS date_start, LAX_STRING(d.account_id) AS account_id, ARRAY(SELECT TO_JSON_STRING(e) FROM UNNEST(JSON_QUERY_ARRAY(d, \'$.conversion_values\')) AS e) AS conversion_values, LAX_FLOAT64(d.inline_post_engagement) AS inline_post_engagement, LAX_STRING(d.adset_id) AS adset_id, LAX_FLOAT64(d.clicks) AS clicks, TIMESTAMP(LAX_STRING(d.created_at)) AS created_at, ARRAY(SELECT TO_JSON_STRING(e) FROM UNNEST(JSON_QUERY_ARRAY(d, \'$.actions\')) AS e) AS actions, _airbyte_ab_id, _airbyte_emitted_at, FROM parsed ) ) Qualify row_number() over(partition by ad_id,date_start order by _airbyte_emitted_at desc) = 1; CREATE OR REPLACE TABLE maplemonk.SAADAA_FACEBOOK_CONSOLIDATED AS select Adset_Name ,Adset_ID ,FB.ad_id ,FB.ad_name ,\'FACEBOOK\' as Account_Name ,Account_ID ,Campaign_Name ,Campaign_ID ,cast(Fb.date_start as date) Date ,SUM(CLICKS) Clicks ,sum(ifnull(inline_link_clicks,0)) Link_Clicks ,SUM(SPEND) Spend ,SUM(IMPRESSIONS) Impressions ,SUM(ifnull(Fc.Conversions,0)) Conversions ,SUM(ifnull(Fcv.Conversion_Value,0)) Conversion_Value ,sum(ifnull(fd.add_to_carts,0)) Add_to_carts ,sum(ifnull(fdv.add_to_cart_value,0)) Add_to_cart_value ,sum(ifnull(fe.landing_page_views,0)) Landing_page_views ,sum(ifnull(ff.initiate_checkouts,0)) Initiate_checkouts ,sum(ifnull(ffv.initiate_checkouts_value,0)) Initiate_checkouts_value ,\'FACEBOOK\' Channel ,\'FACEBOOK\' Account from maplemonk.Saadaa_DB_Facebook_customcampaigns_data FB left join ( select ad_id ,ad_name ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Conversions from maplemonk.Saadaa_DB_Facebook_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fc ON Fb.ad_id = Fc.ad_id and Fb.date_start=Fc.date_start left join ( select ad_id ,ad_name ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Conversion_Value from maplemonk.Saadaa_DB_Facebook_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Fcv ON Fb.ad_id = Fcv.ad_id and Fb.date_start=Fcv.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) add_to_carts from maplemonk.Saadaa_DB_Facebook_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fd ON Fb.ad_id = Fd.ad_id and Fb.date_start=Fd.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Add_to_cart_Value from maplemonk.Saadaa_DB_Facebook_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Fdv ON Fb.ad_id = Fdv.ad_id and Fb.date_start=Fdv.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Landing_page_views from maplemonk.Saadaa_DB_Facebook_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'landing_page_view\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fe ON Fb.ad_id = Fe.ad_id and Fb.date_start=Fe.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Initiate_checkouts from maplemonk.Saadaa_DB_Facebook_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Ff ON Fb.ad_id = Ff.ad_id and Fb.date_start=Ff.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Initiate_checkouts_Value from maplemonk.Saadaa_DB_Facebook_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Ffv ON Fb.ad_id = Ffv.ad_id and Fb.date_start=Ffv.date_start group by Adset_Name, Adset_ID,fb.ad_id,fb.AD_NAME, Account_Name, Account_ID, Campaign_Name, Campaign_ID,Fb.date_start ;",
                    "transaction": true
                }
            ) }}
